    <tbody id="tbody"><tr><td colspan="8" style="text-align:center;color:#6b6a65">暂无数据</td></tr></tbody>
  </table>

  <p class="hint">
    页面每 1 秒向 <code>/api/latest</code> 与 <code>/api/history</code> 查询一次，数值全部来自服务端存储的板端上报记录，页面内没有任何写死的常量。
    停掉板端后数值会冻结，超过阈值即提示「未更新」。
  </p>
</div>

<script>
const $ = (id) => document.getElementById(id);
const fmt = (v, n = 3) => (v === null || v === undefined) ? '—' : Number(v).toFixed(n);

function setPill(cls, text) {
  const p = $('pill');
  p.className = 'pill ' + cls;
  p.textContent = text;
}

async function tick() {
  try {
    const [lr, hr] = await Promise.all([
      fetch('/api/latest').then(r => r.json()),
      fetch('/api/history?limit=8').then(r => r.json())
    ]);

    $('mthr').textContent = (lr.stale_seconds ?? '—') + ' 秒';

    if (!lr.has_data) {
      setPill('idle', '暂无数据');
      $('dev').textContent = 'device: —';
      ['ax','ay','az','gx','gy','gz'].forEach(k => $(k).innerHTML = '—');
      $('mtime').textContent = $('mage').textContent = $('mseq').textContent = $('mip').textContent = '—';
      $('tbody').innerHTML = '<tr><td colspan="8" style="text-align:center;color:#6b6a65">暂无数据</td></tr>';
      return;
    }

    const r = lr.record;
    $('dev').textContent = 'device: ' + r.device_id;
    $('ax').innerHTML = fmt(r.ax) + '<span class="u">g</span>';
    $('ay').innerHTML = fmt(r.ay) + '<span class="u">g</span>';
    $('az').innerHTML = fmt(r.az) + '<span class="u">g</span>';
    $('gx').innerHTML = fmt(r.gx, 1) + '<span class="u">°/s</span>';
    $('gy').innerHTML = fmt(r.gy, 1) + '<span class="u">°/s</span>';
    $('gz').innerHTML = fmt(r.gz, 1) + '<span class="u">°/s</span>';

    $('mtime').textContent = r.server_time;
    $('mage').textContent = r.age_seconds.toFixed(1) + ' 秒';
    $('mseq').textContent = r.seq;
    $('mip').textContent = r.src_ip || '—';

    if (r.stale) {
      setPill('bad', '未更新 · 已 ' + r.age_seconds.toFixed(0) + ' 秒');
    } else {
      setPill('ok', '实时更新中');
    }

    const rows = (hr.records || []).map(x => `<tr>
      <td>${x.server_time}</td>
      <td>${fmt(x.ax)}</td><td>${fmt(x.ay)}</td><td>${fmt(x.az)}</td>
      <td>${fmt(x.gx,1)}</td><td>${fmt(x.gy,1)}</td><td>${fmt(x.gz,1)}</td>
      <td>${x.seq}</td></tr>`).join('');
    $('tbody').innerHTML = rows || '<tr><td colspan="8" style="text-align:center;color:#6b6a65">暂无数据</td></tr>';
  } catch (e) {
    setPill('warn', '无法连接服务');
  }
}

tick();
setInterval(tick, 1000);
</script>
</body>
</html>
"}

