function drawChart() {
  const cv = $('chart');
  const dpr = window.devicePixelRatio || 1;
  const w = cv.clientWidth, h = 240;
  cv.width = w * dpr; cv.height = h * dpr;
  const g = cv.getContext('2d');
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  g.clearRect(0,0,w,h);
  const pts = LAST.slice().reverse();  // ascending
  if (!pts.length) { ... '暂无数据'; return; }
  const keys = SERIES[MODE];
  // padding
  const pl = 46, pr = 12, pt = 10, pb = 22;
  let min = Infinity, max = -Infinity;
  pts.forEach(p => keys.forEach(([k]) => { const v = Number(p[k]); if (v<min) min=v; if (v>max) max=v; }));
  if (!isFinite(min)) { min = -1; max = 1; }
  if (max - min < 1e-6) { max += 0.5; min -= 0.5; }
  const pad = (max-min)*0.12; min -= pad; max += pad;
  const x = i => pl + (w-pl-pr) * (pts.length===1?0.5:i/(pts.length-1));
  const y = v => pt + (h-pt-pb) * (1 - (v-min)/(max-min));
  // grid + y labels
  g.strokeStyle = '#ebeae5'; g.lineWidth = 1; g.fillStyle = '#6b6a65'; g.font = '11px sans-serif'; g.textAlign='right';
  for (let i=0;i<=4;i++){ const v = min + (max-min)*i/4; const yy = y(v);
    g.beginPath(); g.moveTo(pl, yy); g.lineTo(w-pr, yy); g.stroke();
    g.fillText(v.toFixed(2), pl-6, yy+3);
  }
  // x labels: first & last time
  g.textAlign='left'; g.fillStyle='#6b6a65';
  const t0 = pts[0].server_time.slice(11), t1 = pts[pts.length-1].server_time.slice(11);
  g.fillText(t0, pl, h-6); g.textAlign='right'; g.fillText(t1, w-pr, h-6);
  // lines
  keys.forEach(([k,,color]) => {
    g.strokeStyle = color; g.lineWidth = 1.8; g.beginPath();
    pts.forEach((p,i)=>{ const xx=x(i), yy=y(Number(p[k])); i?g.lineTo(xx,yy):g.moveTo(xx,yy); });
    g.stroke();
  });
}
