  1→/* AI 交互课 第1周 —— ESP32 板端固件（待实机验证）
  2→ *
  3→ * 功能：连 WiFi -> I2C 读 MPU6050 -> 每 1 秒 HTTP POST 一条 JSON 到服务端
  4→ *
  5→ * 使用前改下面 5 个宏：WIFI_SSID / WIFI_PASS / SERVER_URL / DEVICE_ID / I2C 引脚
  6→ * 编译烧录：
  7→ *     idf.py set-target esp32
  8→ *     idf.py build
  9→ *     idf.py -p COM3 flash monitor
 10→ *
 11→ * 注意：SERVER_URL 要填电脑的局域网 IP（如 http://192.168.1.23:8000/api/data），
 12→ *       不能用 127.0.0.1 —— 那是板子自己。
 13→ */
 14→
 15→#include <stdio.h>
 16→#include <string.h>
 17→#include "freertos/FreeRTOS.h"
 18→#include "freertos/task.h"
 19→#include "freertos/event_groups.h"
 20→#include "esp_log.h"
 21→#include "esp_wifi.h"
 22→#include "esp_event.h"
 23→#include "esp_netif.h"
 24→#include "esp_http_client.h"
 25→#include "esp_timer.h"
 26→#include "nvs_flash.h"
 27→#include "driver/i2c.h"
 28→
 29→/* ============ 需要按实际情况修改 ============ */
 30→#define WIFI_SSID      "YOUR_WIFI_SSID"
 31→#define WIFI_PASS      "YOUR_WIFI_PASSWORD"
 32→#define SERVER_URL     "http://192.168.1.23:8000/api/data"
 33→#define DEVICE_ID      "team01-esp32"
 34→
 35→#define I2C_SDA_GPIO   21
 36→#define I2C_SCL_GPIO   22
 37→#define I2C_PORT       I2C_NUM_0
 38→#define I2C_FREQ_HZ    400000
 39→#define MPU6050_ADDR   0x68
 40→
 41→#define POST_INTERVAL_MS  1000
 42→/* =========================================== */
 43→
 44→static const char *TAG = "week1";
 45→static EventGroupHandle_t s_wifi_event_group;
 46→#define WIFI_CONNECTED_BIT BIT0
 47→
 48→static void wifi_event_handler(void *arg, esp_event_base_t base,
 49→                               int32_t id, void *data)
 50→{
 51→    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
 52→        esp_wifi_connect();
 53→    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
 54→        ESP_LOGW(TAG, "WiFi 断开，重试中...");
 55→        esp_wifi_connect();
 56→    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
 57→        ip_event_got_ip_t *ev = (ip_event_got_ip_t *)data;
 58→        ESP_LOGI(TAG, "拿到 IP: " IPSTR, IP2STR(&ev->ip_info.ip));
 59→        xEventGroupSetBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
 60→    }
 61→}
 62→
 63→static void wifi_init_sta(void)
 64→{
 65→    s_wifi_event_group = xEventGroupCreate();
 66→    ESP_ERROR_CHECK(esp_netif_init());
 67→    ESP_ERROR_CHECK(esp_event_loop_create_default());
 68→    esp_netif_create_default_wifi_sta();
 69→
 70→    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
 71→    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
 72→
 73→    ESP_ERROR_CHECK(esp_event_handler_register(WIFI_EVENT, ESP_EVENT_ANY_ID,
 74→                                               &wifi_event_handler, NULL));
 75→    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_STA_GOT_IP,
 76→                                               &wifi_event_handler, NULL));
 77→
 78→    wifi_config_t wifi_cfg = {0};
 79→    strncpy((char *)wifi_cfg.sta.ssid, WIFI_SSID, sizeof(wifi_cfg.sta.ssid) - 1);
 80→    strncpy((char *)wifi_cfg.sta.password, WIFI_PASS, sizeof(wifi_cfg.sta.password) - 1);
 81→    wifi_cfg.sta.threshold.authmode = WIFI_AUTH_WPA2_PSK;
 82→
 83→    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
 84→    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_cfg));
 85→    ESP_ERROR_CHECK(esp_wifi_start());
 86→    ESP_LOGI(TAG, "WiFi 启动，等待连接 %s ...", WIFI_SSID);
 87→}
 88→
 89→static void i2c_master_init(void)
 90→{
 91→    i2c_config_t conf = {
 92→        .mode = I2C_MODE_MASTER,
 93→        .sda_io_num = I2C_SDA_GPIO,
 94→        .scl_io_num = I2C_SCL_GPIO,
 95→        .sda_pullup_en = GPIO_PULLUP_ENABLE,
 96→        .scl_pullup_en = GPIO_PULLUP_ENABLE,
 97→        .master.clk_speed = I2C_FREQ_HZ,
 98→    };
 99→    ESP_ERROR_CHECK(i2c_param_config(I2C_PORT, &conf));
100→    ESP_ERROR_CHECK(i2c_driver_install(I2C_PORT, conf.mode, 0, 0, 0));
101→}
102→
103→static esp_err_t mpu6050_write_reg(uint8_t reg, uint8_t val)
104→{
105→    uint8_t buf[2] = {reg, val};
106→    return i2c_master_write_to_device(I2C_PORT, MPU6050_ADDR, buf, 2,
107→                                      pdMS_TO_TICKS(100));
108→}
109→
110→static esp_err_t mpu6050_read(uint8_t reg, uint8_t *out, size_t len)
111→{
112→    return i2c_master_write_read_device(I2C_PORT, MPU6050_ADDR, &reg, 1,
113→                                        out, len, pdMS_TO_TICKS(100));
114→}
115→
116→static void mpu6050_init(void)
117→{
118→    /* PWR_MGMT_1 = 0 -> 退出睡眠，使用内部 8MHz 振荡器 */
119→    ESP_ERROR_CHECK(mpu6050_write_reg(0x6B, 0x00));
120→    vTaskDelay(pdMS_TO_TICKS(100));
121→    /* 量程：加速度 ±2g(默认)，陀螺仪 ±250°/s(默认) */
122→    ESP_LOGI(TAG, "MPU6050 初始化完成");
123→}
124→
125→static esp_err_t http_post_json(const char *json)
126→{
127→    esp_http_client_config_t cfg = {
128→        .url = SERVER_URL,
129→        .method = HTTP_METHOD_POST,
130→        .timeout_ms = 5000,
131→    };
132→    esp_http_client_handle_t client = esp_http_client_init(&cfg);
133→    if (client == NULL) {
134→        return ESP_FAIL;
135→    }
136→    esp_http_client_set_header(client, "Content-Type", "application/json");
137→    esp_http_client_set_post_field(client, json, strlen(json));
138→
139→    esp_err_t err = esp_http_client_perform(client);
140→    if (err == ESP_OK) {
141→        int status = esp_http_client_get_status_code(client);
142→        ESP_LOGI(TAG, "上报完成 HTTP %d", status);
143→        if (status != 200) {
144→            err = ESP_FAIL;
145→        }
146→    } else {
147→        ESP_LOGW(TAG, "上报失败: %s", esp_err_to_name(err));
148→    }
149→    esp_http_client_cleanup(client);
150→    return err;
151→}
152→
153→void app_main(void)
154→{
155→    ESP_ERROR_CHECK(nvs_flash_init());
156→    wifi_init_sta();
157→
158→    /* 等 WiFi 拿到 IP */
159→    xEventGroupWaitBits(s_wifi_event_group, WIFI_CONNECTED_BIT,
160→                        pdFALSE, pdTRUE, portMAX_DELAY);
161→
162→    i2c_master_init();
163→    mpu6050_init();
164→
165→    uint32_t seq = 0;
166→    while (1) {
167→        uint8_t raw[14];
168→        if (mpu6050_read(0x3B, raw, sizeof(raw)) != ESP_OK) {
169→            ESP_LOGE(TAG, "读取 MPU6050 失败");
170→            vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
171→            continue;
172→        }
173→
174→        int16_t ax_raw = (int16_t)((raw[0] << 8) | raw[1]);
175→        int16_t ay_raw = (int16_t)((raw[2] << 8) | raw[3]);
176→        int16_t az_raw = (int16_t)((raw[4] << 8) | raw[5]);
177→        int16_t gx_raw = (int16_t)((raw[8] << 8) | raw[9]);
178→        int16_t gy_raw = (int16_t)((raw[10] << 8) | raw[11]);
179→        int16_t gz_raw = (int16_t)((raw[12] << 8) | raw[13]);
180→
181→        /* 换算成物理单位：±2g -> 16384 LSB/g；±250°/s -> 131 LSB/(°/s) */
182→        float ax = ax_raw / 16384.0f;
183→        float ay = ay_raw / 16384.0f;
184→        float az = az_raw / 16384.0f;
185→        float gx = gx_raw / 131.0f;
186→        float gy = gy_raw / 131.0f;
187→        float gz = gz_raw / 131.0f;
188→
189→        char payload[256];
190→        int n = snprintf(payload, sizeof(payload),
191→                         "{\"device_id\":\"%s\",\"seq\":%lu,\"ts\":%lld,"
192→                         "\"ax\":%.4f,\"ay\":%.4f,\"az\":%.4f,"
193→                         "\"gx\":%.2f,\"gy\":%.2f,\"gz\":%.2f}",
194→                         DEVICE_ID, (unsigned long)seq,
195→                         (long long)(esp_timer_get_time() / 1000),
196→                         ax, ay, az, gx, gy, gz);
197→        if (n > 0 && n < (int)sizeof(payload)) {
198→            ESP_LOGI(TAG, "ax=%.3f ay=%.3f az=%.3f | gx=%.1f gy=%.1f gz=%.1f",
199→                     ax, ay, az, gx, gy, gz);
200→            http_post_json(payload);
201→        }
202→
203→        seq++;
204→        vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
205→    }
206→}
207→

