141→static bool qma7981_init(void)
142→{
143→    uint8_t chip_id = 0;
144→    if (qma_read(0x00, &chip_id, 1) != ESP_OK) {
145→        ESP_LOGE(TAG, "读不到 QMA7981 (0x%02x)，检查地址/接线", QMA7981_ADDR);
146→        return false;
147→    }
148→    ESP_LOGI(TAG, "QMA7981 chip_id = 0x%02x (期望 0xE7)", chip_id);
149→
150→    /* 上电初始化：±2g 量程、带宽档、使能加速度 */
151→    ESP_ERROR_CHECK(qma_write_reg(0x0F, 0x00));  /* RANGE: ±2g */
152→    ESP_ERROR_CHECK(qma_write_reg(0x10, 0x03));  /* BW_LPF 滤波带宽 */
153→    ESP_ERROR_CHECK(qma_write_reg(0x11, 0x80));  /* POWER_CTL: EN_ACC, 主动模式 */
154→    vTaskDelay(pdMS_TO_TICKS(50));
155→    ESP_LOGI(TAG, "QMA7981 初始化完成");
156→    return true;
157→}
