159→static esp_err_t http_post_json(const char *json)
160→{
161→    esp_http_client_config_t cfg = {
162→        .url = SERVER_URL,
163→        .method = HTTP_METHOD_POST,
164→        .timeout_ms = 5000,
165→    };
166→    esp_http_client_handle_t client = esp_http_client_init(&cfg);
167→    if (client == NULL) {
168→        return ESP_FAIL;
169→    }
170→    esp_http_client_set_header(client, "Content-Type", "application/json");
171→    esp_http_client_set_post_field(client, json, strlen(json));
172→
173→    esp_err_t err = esp_http_client_perform(client);
174→    if (err == ESP_OK) {
175→        int status = esp_http_client_get_status_code(client);
176→        ESP_LOGI(TAG, "上报完成 HTTP %d", status);
177→        if (status != 200) {
178→            err = ESP_FAIL;
179→        }
180→    } else {
181→        ESP_LOGW(TAG, "上报失败: %s", esp_err_to_name(err));
182→    }
183→    esp_http_client_cleanup(client);
184→    return err;
185→}
