  1→/* AI 交互课 第1周 —— ESP32-S3-EYE 板端固件（板载 QMA7981 加速度计）
  2→ *
  3→ * 功能：连 WiFi -> I2C 读板载 QMA7981（GPIO4=SDA, GPIO5=SCL, 地址 0x12）
  4→ *       -> 每 1 秒 HTTP POST 一条 JSON 到服务端
  5→ *
  6→ * 注意：QMA7981 只有三轴加速度，没有陀螺仪 —— gx/gy/gz 固定发 0。
  7→ *
  8→ * 使用前改 3 个宏：WIFI_SSID / WIFI_PASS / SERVER_URL
  9→ * 编译烧录（用桌面的 ESP-IDF 5.4 CMD）：
 10→ *     idf.py set-target esp32s3
 11→ *     idf.py build
 12→ *     idf.py -p COM5 flash monitor
 13→ *
 14→ * SERVER_URL 填电脑的局域网 IP（如 http://192.168.1.23:8000/api/data），
 15→ * 不能用 127.0.0.1 —— 那是板子自己。
 16→ */
 17→
 18→#include <stdio.h>
 19→#include <string.h>
 20→#include <math.h>
 21→#include "freertos/FreeRTOS.h"
 22→#include "freertos/task.h"
 23→#include "freertos/event_groups.h"
 24→#include "esp_log.h"
 25→#include "esp_wifi.h"
 26→#include "esp_event.h"
 27→#include "esp_netif.h"
 28→#include "esp_http_client.h"
 29→#include "esp_timer.h"
 30→#include "nvs_flash.h"
 31→#include "driver/i2c.h"
 32→
 33→/* ============ 需要按实际情况修改 ============ */
 34→#define WIFI_SSID      "431"
 35→#define WIFI_PASS      "88888888"
 36→#define SERVER_URL     "http://10.1.41.18:8000/api/data"
 37→#define DEVICE_ID      "team01-esp32s3eye"
 38→
 39→/* ============ ESP32-S3-EYE 固定接线（不用改） ============ */
 40→#define I2C_SDA_GPIO   4      /* 与摄像头 SCCB 共用总线 */
 41→#define I2C_SCL_GPIO   5
 42→#define I2C_PORT       I2C_NUM_0
 43→#define I2C_FREQ_HZ    400000
 44→#define QMA7981_ADDR   0x12
 45→
 46→/* 灵敏度：±2g 量程、14位输出 下每 1g 对应的原始计数值。
 47→ * QMA7981 数据为 14 位左对齐（先组装 16 位再算术右移 2 位），
 48→ * ±2g 满量程 16384 计数跨 4g => 4096 LSB/g。 */
 49→#define QMA_SENS_LSB_PER_G  4096.0f
 50→
 51→#define POST_INTERVAL_MS  1000
 52→/* =========================================== */
 53→
 54→static const char *TAG = "week1";
 55→static EventGroupHandle_t s_wifi_event_group;
 56→#define WIFI_CONNECTED_BIT BIT0
 57→
 58→static void wifi_event_handler(void *arg, esp_event_base_t base,
 59→                               int32_t id, void *data)
 60→{
 61→    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
 62→        esp_wifi_connect();
 63→    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
 64→        ESP_LOGW(TAG, "WiFi 断开，重试中...");
 65→        esp_wifi_connect();
 66→    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
 67→        ip_event_got_ip_t *ev = (ip_event_got_ip_t *)data;
 68→        ESP_LOGI(TAG, "拿到 IP: " IPSTR, IP2STR(&ev->ip_info.ip));
 69→        xEventGroupSetBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
 70→    }
 71→}
 72→
 73→static void wifi_init_sta(void)
 74→{
 75→    s_wifi_event_group = xEventGroupCreate();
 76→    ESP_ERROR_CHECK(esp_netif_init());
 77→    ESP_ERROR_CHECK(esp_event_loop_create_default());
 78→    esp_netif_create_default_wifi_sta();
 79→
 80→    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
 81→    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
 82→
 83→    ESP_ERROR_CHECK(esp_event_handler_register(WIFI_EVENT, ESP_EVENT_ANY_ID,
 84→                                               &wifi_event_handler, NULL));
 85→    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_STA_GOT_IP,
 86→                                               &wifi_event_handler, NULL));
 87→
 88→    wifi_config_t wifi_cfg = {0};
 89→    strncpy((char *)wifi_cfg.sta.ssid, WIFI_SSID, sizeof(wifi_cfg.sta.ssid) - 1);
 90→    strncpy((char *)wifi_cfg.sta.password, WIFI_PASS, sizeof(wifi_cfg.sta.password) - 1);
 91→    wifi_cfg.sta.threshold.authmode = WIFI_AUTH_WPA2_PSK;
 92→
 93→    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
 94→    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_cfg));
 95→    ESP_ERROR_CHECK(esp_wifi_start());
 96→    ESP_LOGI(TAG, "WiFi 启动，等待连接 %s ...", WIFI_SSID);
 97→}
 98→
 99→static void i2c_master_init(void)
100→{
101→    i2c_config_t conf = {
102→        .mode = I2C_MODE_MASTER,
103→        .sda_io_num = I2C_SDA_GPIO,
104→        .scl_io_num = I2C_SCL_GPIO,
105→        .sda_pullup_en = GPIO_PULLUP_ENABLE,
106→        .scl_pullup_en = GPIO_PULLUP_ENABLE,
107→        .master.clk_speed = I2C_FREQ_HZ,
108→    };
109→    ESP_ERROR_CHECK(i2c_param_config(I2C_PORT, &conf));
110→    ESP_ERROR_CHECK(i2c_driver_install(I2C_PORT, conf.mode, 0, 0, 0));
111→}
112→
113→/* 启动时扫一遍 I2C 总线，把挂着的设备地址打出来 —— 首次调试定位问题用
114→ * 注意：探测必须用 1 字节真实读，零长度读在本驱动上会全程报
115→ * "i2c data read length error" 且永远探测不到设备 */
116→static void i2c_scan(void)
117→{
118→    ESP_LOGI(TAG, "I2C 扫描 (SDA=%d SCL=%d)...", I2C_SDA_GPIO, I2C_SCL_GPIO);
119→    for (uint8_t addr = 1; addr < 127; addr++) {
120→        uint8_t dummy;
121→        esp_err_t err = i2c_master_write_read_device(I2C_PORT, addr, &dummy, 0,
122→                                                     &dummy, 1,
123→                                                     pdMS_TO_TICKS(20));
124→        if (err == ESP_OK) {
125→            ESP_LOGI(TAG, "  发现设备: 0x%02x%s", addr,
126→                     addr == QMA7981_ADDR ? "  <-- QMA7981" : "");
127→        }
128→    }
129→}
130→
131→static esp_err_t qma_write_reg(uint8_t reg, uint8_t val)
132→{
133→    uint8_t buf[2] = {reg, val};
134→    return i2c_master_write_to_device(I2C_PORT, QMA7981_ADDR, buf, 2,
135→                                      pdMS_TO_TICKS(100));
136→}
137→
138→static esp_err_t qma_read(uint8_t reg, uint8_t *out, size_t len)
139→{
140→    return i2c_master_write_read_device(I2C_PORT, QMA7981_ADDR, &reg, 1,
141→                                        out, len, pdMS_TO_TICKS(100));
142→}
143→
144→static bool qma7981_init(void)
145→{
146→    uint8_t chip_id = 0;
147→    if (qma_read(0x00, &chip_id, 1) != ESP_OK) {
148→        ESP_LOGE(TAG, "读不到 QMA7981 (0x%02x)，检查地址/接线", QMA7981_ADDR);
149→        return false;
150→    }
151→    ESP_LOGI(TAG, "QMA7981 chip_id = 0x%02x", chip_id);
152→    /* 本板实测为 0x90；不同硅版本有差异（0xE7 亦见诸资料），只提示不拦 */
153→    if (chip_id != 0x90 && chip_id != 0xE7) {
154→        ESP_LOGW(TAG, "chip_id 非常见值(0x90/0xE7)，继续尝试");
155→    }
156→
157→    /* 软复位（0x36=SOFT_RESET 写 0xB6 后回写 0x00）：
158→     * 实测本板上电后寄存器写入不生效、Y 轴数据冻结，软复位后恢复正常 */
159→    qma_write_reg(0x36, 0xB6);
160→    vTaskDelay(pdMS_TO_TICKS(20));
161→    qma_write_reg(0x36, 0x00);
162→    vTaskDelay(pdMS_TO_TICKS(20));
163→
164→    /* 按参考驱动顺序：先退出睡眠，再设量程/带宽 */
165→    ESP_ERROR_CHECK(qma_write_reg(0x11, 0xC0));  /* POWER: 退出睡眠，主动模式 */
166→    vTaskDelay(pdMS_TO_TICKS(20));
167→    ESP_ERROR_CHECK(qma_write_reg(0x0F, 0x01));  /* RANGE: ±2g (QMA_RANGE_2G=0b0001) */
168→    ESP_ERROR_CHECK(qma_write_reg(0x10, 0x05));  /* BW: 1024Hz (合法值 0b101) */
169→    vTaskDelay(pdMS_TO_TICKS(50));
170→
171→    /* 回读配置，确认写入是否生效 */
172→    uint8_t cfg[3];
173→    qma_read(0x0F, cfg, 3);
174→    ESP_LOGI(TAG, "配置回读 0F/10/11 = %02x %02x %02x (期望 01 05 C0)",
175→             cfg[0], cfg[1], cfg[2]);
176→    ESP_LOGI(TAG, "QMA7981 初始化完成");
177→    return true;
178→}
179→
180→static esp_err_t http_post_json(const char *json)
181→{
182→    esp_http_client_config_t cfg = {
183→        .url = SERVER_URL,
184→        .method = HTTP_METHOD_POST,
185→        .timeout_ms = 5000,
186→    };
187→    esp_http_client_handle_t client = esp_http_client_init(&cfg);
188→    if (client == NULL) {
189→        return ESP_FAIL;
190→    }
191→    esp_http_client_set_header(client, "Content-Type", "application/json");
192→    esp_http_client_set_post_field(client, json, strlen(json));
193→
194→    esp_err_t err = esp_http_client_perform(client);
195→    if (err == ESP_OK) {
196→        int status = esp_http_client_get_status_code(client);
197→        ESP_LOGI(TAG, "上报完成 HTTP %d", status);
198→        if (status != 200) {
199→            err = ESP_FAIL;
200→        }
201→    } else {
202→        ESP_LOGW(TAG, "上报失败: %s", esp_err_to_name(err));
203→    }
204→    esp_http_client_cleanup(client);
205→    return err;
206→}
207→
208→/* QMA7981 14位数据组装（Rev C 手册）：
209→ * MSB 寄存器 = DX[13:6]，LSB 寄存器 bit5:0 = DX[5:0]，bit7 = NEWDATA 标志
210→ * 14位二进制补码，bit13 为符号位 */
211→static inline int16_t qma_assemble14(uint8_t lsb, uint8_t msb)
212→{
213→    int16_t v = (int16_t)(((uint16_t)msb << 6) | (lsb & 0x3F));
214→    if (v & 0x2000) {
215→        v -= 0x4000;
216→    }
217→    return v;
218→}
219→
220→void app_main(void)
221→{
222→    ESP_ERROR_CHECK(nvs_flash_init());
223→    i2c_master_init();
224→    i2c_scan();
225→
226→    if (!qma7981_init()) {
227→        ESP_LOGE(TAG, "IMU 初始化失败，停机（不发送假数据）");
228→        return;
229→    }
230→
231→    wifi_init_sta();
232→    /* 等 WiFi 拿到 IP */
233→    xEventGroupWaitBits(s_wifi_event_group, WIFI_CONNECTED_BIT,
234→                        pdFALSE, pdTRUE, portMAX_DELAY);
235→
236→    uint32_t seq = 0;
237→    while (1) {
238→        uint8_t raw[6];
239→        if (qma_read(0x01, raw, sizeof(raw)) != ESP_OK) {
240→            ESP_LOGE(TAG, "读取 QMA7981 数据寄存器(0x01)失败");
241→            vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
242→            continue;
243→        }
244→
245→        /* QMA7981：0x01 起 6 字节 = [DXL,DXM,DYL,DYM,DZL,DZM]，LSB 高位含 NEWDATA 标志 */
246→        int16_t ax_raw = qma_assemble14(raw[0], raw[1]);
247→        int16_t ay_raw = qma_assemble14(raw[2], raw[3]);
248→        int16_t az_raw = qma_assemble14(raw[4], raw[5]);
249→
250→        float ax = ax_raw / QMA_SENS_LSB_PER_G;
251→        float ay = ay_raw / QMA_SENS_LSB_PER_G;
252→        float az = az_raw / QMA_SENS_LSB_PER_G;
253→
254→        char payload[256];
255→        int n = snprintf(payload, sizeof(payload),
256→                         "{\"device_id\":\"%s\",\"seq\":%lu,\"ts\":%lld,"
257→                         "\"ax\":%.4f,\"ay\":%.4f,\"az\":%.4f,"
258→                         "\"gx\":0.00,\"gy\":0.00,\"gz\":0.00}",
259→                         DEVICE_ID, (unsigned long)seq,
260→                         (long long)(esp_timer_get_time() / 1000),
261→                         ax, ay, az);
262→        if (n > 0 && n < (int)sizeof(payload)) {
263→            float norm = sqrtf(ax * ax + ay * ay + az * az);
264→            ESP_LOGI(TAG, "raw=[%d %d %d] ax=%.3f ay=%.3f az=%.3f |a|=%.3f",
265→                     ax_raw, ay_raw, az_raw, ax, ay, az, norm);
266→            http_post_json(payload);
267→        }
268→
269→        /* 临时诊断：每 2 秒 dump 0x00~0x3F 寄存器，用于确认数据寄存器布局 */
270→        if (seq % 2 == 0) {
271→            uint8_t d[64];
272→            if (qma_read(0x00, d, sizeof(d)) == ESP_OK) {
273→                ESP_LOGI(TAG, "REGS00-1F: "
274→                              "%02x %02x %02x %02x %02x %02x %02x %02x "
275→                              "%02x %02x %02x %02x %02x %02x %02x %02x "
276→                              "%02x %02x %02x %02x %02x %02x %02x %02x "
277→                              "%02x %02x %02x %02x %02x %02x %02x %02x",
278→                         d[0], d[1], d[2], d[3], d[4], d[5], d[6], d[7],
279→                         d[8], d[9], d[10], d[11], d[12], d[13], d[14], d[15],
280→                         d[16], d[17], d[18], d[19], d[20], d[21], d[22], d[23],
281→                         d[24], d[25], d[26], d[27], d[28], d[29], d[30], d[31]);
282→                ESP_LOGI(TAG, "REGS20-3F: "
283→                              "%02x %02x %02x %02x %02x %02x %02x %02x "
284→                              "%02x %02x %02x %02x %02x %02x %02x %02x "
285→                              "%02x %02x %02x %02x %02x %02x %02x %02x "
286→                              "%02x %02x %02x %02x %02x %02x %02x %02x",
287→                         d[32], d[33], d[34], d[35], d[36], d[37], d[38], d[39],
288→                         d[40], d[41], d[42], d[43], d[44], d[45], d[46], d[47],
289→                         d[48], d[49], d[50], d[51], d[52], d[53], d[54], d[55],
290→                         d[56], d[57], d[58], d[59], d[60], d[61], d[62], d[63]);
291→            }
292→        }
293→
294→        seq++;
295→        vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
296→    }
297→}
