 93→/* MJPEG 流 handler：客户端不断开就一直推帧 */
 94→static esp_err_t stream_handler(httpd_req_t *req)
 95→{
 96→    camera_fb_t *fb = NULL;
 97→    char part_hdr[64];
 98→    int n;
 99→
100→    esp_err_t res = httpd_resp_set_type(req, STREAM_CONTENT_TYPE);
101→    if (res != ESP_OK) {
102→        return res;
103→    }
104→
105→    /* 关掉这个 sockfd 的 Nagle，减小片段延迟 */
106→    httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");
107→
108→    while (true) {
109→        fb = esp_camera_fb_get();
110→        if (!fb) {
111→            ESP_LOGE(TAG, "取帧失败");
112→            res = ESP_FAIL;
113→            break;
114→        }
115→
116→        /* 帧头 */
117→        n = snprintf(part_hdr, sizeof(part_hdr), STREAM_PART_HDR, (unsigned)fb->len);
118→        if (n < 0 || n >= (int)sizeof(part_hdr)) {
119→            esp_camera_fb_return(fb);
120→            res = ESP_FAIL;
121→            break;
122→        }
123→        res = httpd_resp_send_chunk(req, STREAM_BOUNDARY, strlen(STREAM_BOUNDARY));
124→        if (res != ESP_OK) { esp_camera_fb_return(fb); break; }
125→        res = httpd_resp_send_chunk(req, part_hdr, n);
126→        if (res != ESP_OK) { esp_camera_fb_return(fb); break; }
127→
128→        /* 帧数据 */
129→        res = httpd_resp_send_chunk(req, (const char *)fb->buf, fb->len);
130→        esp_camera_fb_return(fb);
131→        if (res != ESP_OK) {
132→            /* 客户端断开或 sock 出错，退出本次连接等下一次请求 */
133→            break;
134→        }
135→    }
136→
137→    ESP_LOGI(TAG, "视频流连接结束: %s", esp_err_to_name(res));
138→    return res;
139→}
