142→static esp_err_t capture_handler(httpd_req_t *req)
143→{
144→    camera_fb_t *fb = esp_camera_fb_get();
145→    if (!fb) {
146→        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "取帧失败");
147→        return ESP_FAIL;
148→    }
149→    httpd_resp_set_type(req, "image/jpeg");
150→    httpd_resp_set_hdr(req, "Content-Disposition", "inline; filename=capture.jpg");
151→    httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");
152→    esp_err_t res = httpd_resp_send(req, (const char *)fb->buf, fb->len);
153→    esp_camera_fb_return(fb);
154→    return res;
155→}
