static esp_err_t stream_handler(httpd_req_t *req)
{
    /* 名额控制：超出就快速失败，而不是把唯一的 httpd 线程占住 */
    xSemaphoreTake(s_cli_mutex, portMAX_DELAY);
    bool ok = (s_cli_count < CAM_MAX_STREAM_CLIENTS);
    if (ok) s_cli_count++;
    xSemaphoreGive(s_cli_mutex);

    if (!ok) {
        ESP_LOGW(TAG, "客户端数已达上限 %d，拒绝本次连接", CAM_MAX_STREAM_CLIENTS);
        httpd_resp_set_type(req, "text/plain; charset=utf-8");
        httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");
        httpd_resp_set_status(req, "503 Service Unavailable");
        httpd_resp_send(req, "busy", HTTPD_RESP_USE_STRLEN);
        return ESP_OK;
    }

    httpd_req_t *async_req = NULL;
    esp_err_t err = httpd_req_async_handler_begin(req, &async_req);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "异步槽位不足: %s", esp_err_to_name(err));
        /* 名额回收 */
        xSemaphoreTake(s_cli_mutex, portMAX_DELAY); s_cli_count--; xSemaphoreGive(s_cli_mutex);
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "async busy");
        return ESP_FAIL;
    }

    /* 关键：这里立刻返回，httpd 主线程回到 select 循环，
     * 后续请求（包括 /capture、新的重连）才能被处理 */
    static BaseType_t core = 1;
    BaseType_t ret = xTaskCreatePinnedToCore(stream_task, "cam_stream", 8192, async_req, 6, NULL, 1);
    if (ret != pdPASS) {
        httpd_req_async_handler_complete(async_req);
        decrement;
        httpd_resp_send_err(req, HTTPD_500_INTERNAL_SERVER_ERROR, "task fail");
        return ESP_FAIL;
    }
    return ESP_OK;
}
