 * 之前只有一行 error 监听，一旦连接中断就永远停在「未连接」，只能手动刷新页面。
 * 现在做三件事：
 *   1) 每次重连都换一个 URL 时间戳，避免浏览器把上一次的失败结果缓存住；
 *   2) 失败后按 2 秒递增退避重试，不再一次性判死；
 *   3) 每 3 秒 ping 一次板子的 /ping（毫秒级返回）。连它都超时 = 板子服务被堵死，
 *      这时主动掐掉旧连接重建；/ping 还活着但报告 clients=0 = 我们的那条视频流
 *      其实已经断了，页面却不知道（画面停在最后一帧），同样重建。 */
(function mountCamera() {
  const img = document.getElementById('camStream');
  const st  = document.getElementById('camStatus');
  const btn = document.getElementById('btnCamRe');
  if (!img) return;

  let retries = 0;            // 连续失败次数
  let retryTimer = null;      // 重试定时器
  let everOK = false;         // 是否曾经连上过
  let deadVotes = 0;          // /ping 连续失败次数
  let zeroVotes = 0;          // /ping 活着但自称 0 客户端的次数

  function text(s) { st.textContent = s; }

  function connect() {
    clearTimeout(retryTimer);
    if (retries === 0) text('连接中…');
    else text('第 ' + retries + ' 次重连…');

    img.onload  = function () {
      retries = 0; zeroVotes = 0; everOK = true;
      text('实时画面 · 已连接');
    };
    img.onerror = function () {
      retries++;
      if (retries > 20) {
        text('未连接 · 请给板子重新上电后刷新本页面');
        return;
      }
      const wait = Math.min(2 * retries, 10);   // 2s、4s…封顶 10s 退避
      text('未连接 · ' + wait + ' 秒后重试（第 ' + retries + ' 次）');
      retryTimer = setTimeout(connect, wait * 1000);
    };
    /* 时间戳是必须的：不带它会命中浏览器缓存的重定向/错误状态 */
    img.src = CAM_BASE + '/stream?nocache=' + Date.now();
  }

  function hardReconnect(reason) {
    text('检测到' + reason + '，正在重建连接…');
    retries = 0; zeroVotes = 0; deadVotes = 0;
    img.onload = img.onerror = null;
    img.src = '';                       // 先掐断，释放板端名额
