  /* 解析状态端点，回答一个问题：画面还在流动吗？ */
  function parseLive(r, body) {
    if (CAM_MODE === 'server') {
      try {
        const j = JSON.parse(body);
        const age = j.last_frame_age;
        const flowing = j.state === 'streaming' && age !== null && age < 3;
        const note = age === null ? '尚无画面'
                                  : ' ' + age.toFixed(1) + ' 秒前的帧';
        return { alive: flowing, flowing: flowing, note: note, detail: j };
      } catch (e) {
        return { alive: false, flowing: false, note: '状态解析失败' };
      }
    }
    const m = body.match(/clients=(\d+)\/(\d+)/);
    const clients = m ? Number(m[1]) : null;
    return {
      alive: r.ok && clients !== null && clients > 0,
      flowing: clients > 0,
      note: clients === null ? '' : (clients + ' 路直连'),
    };
  }

  /* 心跳：判断取流服务是不是还活着、画面是不是还在动 */
  async function heartbeat() {
    if (document.hidden) return;        // 页面在后台就别添乱
    const ctl = new AbortController();
    const to = setTimeout(() => ctl.abort(), 4000);
    try {
      const r = await fetch(CAM_HEARTBEAT + '?nocache=' + Date.now(),
                            { cache: 'no-store', signal: ctl.signal });
      const body = await r.text();
      clearTimeout(to);
      deadVotes = 0;
      const s = parseLive(r, body);

      if (!s.alive) {
        /* 服务在，但没有画面流动 —— 我们的那条流其实已经断了 */
        if (++zeroVotes >= 2) hardReconnect('画面已停止');
        else text('实时画面 · 已连接（' + s.note.trim() + '）');
      } else {
        zeroVotes = 0;
        if (!everOK) text('服务在线，正在取画面…');
        else text('实时画面 · 已连接（' + s.note.trim() + '）');
      }
    } catch (e) {
      clearTimeout(to);
      if (++deadVotes >= 2) {
        deadVotes = 0;
        hardReconnect(CAM_MODE === 'server' ? '服务器无响应' : '板子无响应');
      } else if (retries === 0) {
        text('连接中…');
      }
    }
