 45→/* ============ 需要按实际情况修改 ============ */
 46→#define WIFI_SSID      "431"
 47→#define WIFI_PASS      "88888888"
 48→#define SERVER_URL     "http://10.1.41.18:8000/api/data"
 49→#define DEVICE_ID      "team01-esp32s3eye"
 50→
 51→/* ============ ESP32-S3-EYE 固定接线（不用改） ============ */
 52→#define I2C_SDA_GPIO   4      /* 与摄像头 SCCB 共用总线 */
 53→#define I2C_SCL_GPIO   5
 54→#define I2C_PORT       I2C_NUM_0
 55→#define I2C_FREQ_HZ    400000
 56→#define QMA6100P_ADDR   0x12
 57→
 58→/* 灵敏度：±2g 量程、14位输出 下每 1g 对应的原始计数值。
 59→ * QMA6100P 数据为 14 位左对齐（先组装 16 位再算术右移 2 位），
 60→ * ±2g 满量程 16384 计数跨 4g => 4096 LSB/g。 */
 61→#define QMA_SENS_LSB_PER_G  4096.0f
 62→
 63→#define POST_INTERVAL_MS  1000
 64→
 65→/* ===== 实测标定（旋转实验：面朝上/朝下静止两点法拟合） =====
 66→ * 本板 QMA6100P（chip_id 0x90）零偏偏大：未标定静止模长 0.78~1.6g 漂移。
 67→ * X 零偏 -0.553g、Y 零偏 -0.148g、Z 零偏 +0.389g、Z 灵敏度系数 0.912，
 68→ * 标定后各静置姿态模长 0.97~1.01。换板子需重新标定。 */
 69→#define CAL_X_OFF    2265.0f   /* 计数 = 0.553g * 4096 */
 70→#define CAL_Y_OFF     608.0f   /* 计数 = 0.148g * 4096 */
 71→#define CAL_Z_OFF    1594.0f   /* 计数 = 0.389g * 4096 */
 72→#define CAL_Z_SCALE    0.912f
 73→/* =========================================== */
 74→/* =========================================== */
