 95→static void wifi_init_sta(void)
 96→{
 97→    s_wifi_event_group = xEventGroupCreate();
 98→    ESP_ERROR_CHECK(esp_netif_init());
 99→    ESP_ERROR_CHECK(esp_event_loop_create_default());
100→    esp_netif_create_default_wifi_sta();
101→
102→    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
103→    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
104→
105→    ESP_ERROR_CHECK(esp_event_handler_register(WIFI_EVENT, ESP_EVENT_ANY_ID,
106→                                               &wifi_event_handler, NULL));
107→    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_STA_GOT_IP,
108→                                               &wifi_event_handler, NULL));
109→
110→    wifi_config_t wifi_cfg = {0};
111→    strncpy((char *)wifi_cfg.sta.ssid, WIFI_SSID, sizeof(wifi_cfg.sta.ssid) - 1);
112→    strncpy((char *)wifi_cfg.sta.password, WIFI_PASS, sizeof(wifi_cfg.sta.password) - 1);
113→    wifi_cfg.sta.threshold.authmode = WIFI_AUTH_WPA2_PSK;
114→
115→    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
116→    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_cfg));
117→    ESP_ERROR_CHECK(esp_wifi_start());
118→    ESP_LOGI(TAG, "WiFi 启动，等待连接 %s ...", WIFI_SSID);
119→}
