  1→/* AI 交互课 第1周 —— ESP32-S3-EYE 板端固件（板载三轴加速度计）
  2→ *
  3→ * 功能：连 WiFi -> I2C 读板载加速度计（GPIO4=SDA, GPIO5=SCL, 地址 0x12）
  4→ *       -> 每 1 秒 HTTP POST 一条 JSON 到服务端
  5→ *
  6→ * ====== 关于芯片型号（重要，调试踩坑的根源）======
  7→ * 原理图和官方手册标注的是 QMA7981，但**本板实装为 QMA6100P**。
  8→ * 两者是 pin-to-pin 兼容的换代关系（QMA7981 已 EOL 停产），封装、
  9→ * I2C 地址(0x12)、14 位 ADC 都一样，所以硬件上换料看不出来。
 10→ * 本板的实测证据（上电时 imu_identify() 会自动打印一遍）：
 11→ *   1) CHIP_ID(0x00) = 0x90  -> QMA6100P（QMA7981 公开手册为 0xE7）
 12→ *   2) QMA6100P 手册特有寄存器 0x33/0x45/0x46/0x4A/0x56/0x5F 均有有效应答
 13→ *   3) 量程位编码 0x01/0x02/0x04/0x08/0x0F(±2/4/8/16/32g) 全部被接受，
 14→ *      而 0x00 是非法值 —— 当初按 QMA7981 手册写 0x00 导致模长异常 1.5g
 15→ * 结论：本驱动按 QMA6100P 的真实寄存器行为编写，不要照 QMA7981 手册改。
 16→ *
 17→ * 注意：QMA6100P 只有三轴加速度，没有陀螺仪 —— gx/gy/gz 固定发 0。
 18→ *
 19→ * 使用前改 3 个宏：WIFI_SSID / WIFI_PASS / SERVER_URL
 20→ * 编译烧录（用桌面的 ESP-IDF 5.4 CMD）：
 21→ *     idf.py set-target esp32s3
 22→ *     idf.py build
 23→ *     idf.py -p COM5 flash monitor
 24→ *
 25→ * SERVER_URL 填电脑的局域网 IP（如 http://192.168.1.23:8000/api/data），
 26→ * 不能用 127.0.0.1 —— 那是板子自己。
 27→ */
 28→
 29→#include <stdio.h>
 30→#include <string.h>
 31→#include <math.h>
 32→#include "freertos/FreeRTOS.h"
 33→#include "freertos/task.h"
 34→#include "freertos/event_groups.h"
 35→#include "esp_log.h"
 36→#include "esp_wifi.h"
 37→#include "esp_event.h"
 38→#include "esp_netif.h"
 39→#include "esp_http_client.h"
 40→#include "esp_timer.h"
 41→#include "nvs_flash.h"
 42→#include "driver/i2c.h"
 43→#include "camera_stream.h"
