242→static esp_err_t http_post_json(const char *json)
243→{
244→    esp_http_client_config_t cfg = {
245→        .url = SERVER_URL,
246→        .method = HTTP_METHOD_POST,
247→        .timeout_ms = 5000,
248→    };
249→    esp_http_client_handle_t client = esp_http_client_init(&cfg);
250→    if (client == NULL) {
251→        return ESP_FAIL;
252→    }
253→    esp_http_client_set_header(client, "Content-Type", "application/json");
254→    esp_http_client_set_post_field(client, json, strlen(json));
255→
256→    esp_err_t err = esp_http_client_perform(client);
257→    if (err == ESP_OK) {
258→        int status = esp_http_client_get_status_code(client);
259→        ESP_LOGI(TAG, "上报完成 HTTP %d", status);
260→        if (status != 200) {
261→            err = ESP_FAIL;
262→        }
263→    } else {
264→        ESP_LOGW(TAG, "上报失败: %s", esp_err_to_name(err));
265→    }
266→    esp_http_client_cleanup(client);
267→    return err;
268→}
