        float ay = ay_raw / QMA_SENS_LSB_PER_G;
        float az = az_raw / QMA_SENS_LSB_PER_G;

        ESP_LOGI(TAG, "ax=%.3f ay=%.3f az=%.3f |a|=%.3f",
                 ax, ay, az, sqrtf(ax*ax + ay*ay + az*az));
