166→static bool qma6100p_init(void)
167→{
168→    uint8_t chip_id = 0;
169→    if (qma_read(0x00, &chip_id, 1) != ESP_OK) {
170→        ESP_LOGE(TAG, "读不到 QMA6100P (0x%02x)，检查地址/接线", QMA6100P_ADDR);
171→        return false;
172→    }
173→    ESP_LOGI(TAG, "QMA6100P chip_id = 0x%02x", chip_id);
174→    /* 本板实测为 0x90；不同硅版本有差异（0xE7 亦见诸资料），只提示不拦 */
175→    if (chip_id != 0x90 && chip_id != 0xE7) {
176→        ESP_LOGW(TAG, "chip_id 非常见值(0x90/0xE7)，继续尝试");
177→    }
178→
179→    /* 软复位（0x36=SOFT_RESET 写 0xB6 后回写 0x00）：
180→     * 实测本板上电后寄存器写入不生效、Y 轴数据冻结，软复位后恢复正常 */
181→    qma_write_reg(0x36, 0xB6);
182→    vTaskDelay(pdMS_TO_TICKS(20));
183→    qma_write_reg(0x36, 0x00);
184→    vTaskDelay(pdMS_TO_TICKS(20));
185→
186→    /* 按参考驱动顺序：先退出睡眠，再设量程/带宽 */
187→    ESP_ERROR_CHECK(qma_write_reg(0x11, 0xC0));  /* POWER: 退出睡眠，主动模式 */
188→    vTaskDelay(pdMS_TO_TICKS(20));
189→    ESP_ERROR_CHECK(qma_write_reg(0x0F, 0x01));  /* RANGE: ±2g (QMA_RANGE_2G=0b0001) */
190→    ESP_ERROR_CHECK(qma_write_reg(0x10, 0x05));  /* BW: 1024Hz (合法值 0b101) */
191→    vTaskDelay(pdMS_TO_TICKS(50));
192→
193→    /* 回读配置，确认写入是否生效 */
194→    uint8_t cfg[3];
195→    qma_read(0x0F, cfg, 3);
196→    ESP_LOGI(TAG, "配置回读 0F/10/11 = %02x %02x %02x (期望 01 05 C0)",
197→             cfg[0], cfg[1], cfg[2]);
198→    ESP_LOGI(TAG, "加速度计初始化完成");
199→    return true;
200→}
