121→static void i2c_master_init(void)
122→{
123→    i2c_config_t conf = {
124→        .mode = I2C_MODE_MASTER,
125→        .sda_io_num = I2C_SDA_GPIO,
126→        .scl_io_num = I2C_SCL_GPIO,
127→        .sda_pullup_en = GPIO_PULLUP_ENABLE,
128→        .scl_pullup_en = GPIO_PULLUP_ENABLE,
129→        .master.clk_speed = I2C_FREQ_HZ,
130→    };
131→    ESP_ERROR_CHECK(i2c_param_config(I2C_PORT, &conf));
132→    ESP_ERROR_CHECK(i2c_driver_install(I2C_PORT, conf.mode, 0, 0, 0));
133→}
134→
135→/* 启动时扫一遍 I2C 总线，把挂着的设备地址打出来 —— 首次调试定位问题用
136→ * 注意：探测必须用 1 字节真实读，零长度读在本驱动上会全程报
137→ * "i2c data read length error" 且永远探测不到设备 */
138→static void i2c_scan(void)
139→{
140→    ESP_LOGI(TAG, "I2C 扫描 (SDA=%d SCL=%d)...", I2C_SDA_GPIO, I2C_SCL_GPIO);
141→    for (uint8_t addr = 1; addr < 127; addr++) {
142→        uint8_t dummy;
143→        esp_err_t err = i2c_master_write_read_device(I2C_PORT, addr, &dummy, 0,
144→                                                     &dummy, 1,
145→                                                     pdMS_TO_TICKS(20));
146→        if (err == ESP_OK) {
147→            ESP_LOGI(TAG, "  发现设备: 0x%02x%s", addr,
148→                     addr == QMA6100P_ADDR ? "  <-- 加速度计(QMA6100P)" : "");
149→        }
150→    }
151→}
152→
153→static esp_err_t qma_write_reg(uint8_t reg, uint8_t val)
154→{
155→    uint8_t buf[2] = {reg, val};
156→    return i2c_master_write_to_device(I2C_PORT, QMA6100P_ADDR, buf, 2,
157→                                      pdMS_TO_TICKS(100));
158→}
159→
160→static esp_err_t qma_read(uint8_t reg, uint8_t *out, size_t len)
161→{
162→    return i2c_master_write_read_device(I2C_PORT, QMA6100P_ADDR, &reg, 1,
163→                                        out, len, pdMS_TO_TICKS(100));
164→}
165→
166→static bool qma6100p_init(void)
167→{
168→    uint8_t chip_id = 0;
169→    if (qma_read(0x00, &chip_id, 1) != ESP_OK) {
170→        ESP_LOGE(TAG, "读不到 QMA6100P (0x%02x)，检查地址/接线", QMA6100P_ADDR);
171→        return false;
172→    }
173→    ESP_LOGI(TAG, "QMA6100P chip_id = 0x%02x", chip_id);
174→    /* 本板实测为 0x90；不同硅版本有差异（0xE7 亦见诸资料），只提示不拦 */
175→    if (chip_id != 0x90 && chip_id != 0xE7) {
176→        ESP_LOGW(TAG, "chip_id 非常见值(0x90/0xE7)，继续尝试");
177→    }
178→
179→    /* 软复位（0x36=SOFT_RESET 写 0xB6 后回写 0x00）：
180→     * 实测本板上电后寄存器写入不生效、Y 轴数据冻结，软复位后恢复正常 */
181→    qma_write_reg(0x36, 0xB6);
182→    vTaskDelay(pdMS_TO_TICKS(20));
183→    qma_write_reg(0x36, 0x00);
184→    vTaskDelay(pdMS_TO_TICKS(20));
185→
186→    /* 按参考驱动顺序：先退出睡眠，再设量程/带宽 */
187→    ESP_ERROR_CHECK(qma_write_reg(0x11, 0xC0));  /* POWER: 退出睡眠，主动模式 */
188→    vTaskDelay(pdMS_TO_TICKS(20));
189→    ESP_ERROR_CHECK(qma_write_reg(0x0F, 0x01));  /* RANGE: ±2g (QMA_RANGE_2G=0b0001) */
190→    ESP_ERROR_CHECK(qma_write_reg(0x10, 0x05));  /* BW: 1024Hz (合法值 0b101) */
191→    vTaskDelay(pdMS_TO_TICKS(50));
192→
193→    /* 回读配置，确认写入是否生效 */
194→    uint8_t cfg[3];
195→    qma_read(0x0F, cfg, 3);
196→    ESP_LOGI(TAG, "配置回读 0F/10/11 = %02x %02x %02x (期望 01 05 C0)",
197→             cfg[0], cfg[1], cfg[2]);
198→    ESP_LOGI(TAG, "加速度计初始化完成");
199→    return true;
200→}
201→
202→/* 型号鉴定：原理图/手册标 QMA7981，但官方 BSP 只有 qma6100p 组件。
203→ * 用三条独立证据确认实装型号：
204→ *   1) CHIP_ID(0x00)：QMA6100P=0x90，QMA7981=0xE7
205→ *   2) QMA6100P 手册特有寄存器（0x33/0x45/0x46/0x4A/0x56/0x5F）是否有有效内容
206→ *   3) 量程支持性：QMA6100P 支持到 ±32g(0b1111)，QMA7981 老手册只到 ±8g/±16g
207→ * 鉴定结束后把量程恢复为 ±2g。 */
208→static void imu_identify(void)
209→{
210→    uint8_t v = 0;
211→    ESP_LOGI(TAG, "======== 型号鉴定 ========");
212→
213→    qma_read(0x00, &v, 1);
214→    ESP_LOGI(TAG, "ID  CHIP_ID(0x00) = 0x%02x  (0x90=QMA6100P / 0xE7=QMA7981)", v);
215→
216→    uint8_t probe[]   = {0x33, 0x45, 0x46, 0x4A, 0x56, 0x5F};
217→    const char *nm[]  = {"NVM", "CHIP_STATE", "ULPS", "TST0_ANA", "AFE_ANA", "TST1_ANA"};
218→    for (int i = 0; i < 6; i++) {
219→        uint8_t r = 0xFF;
220→        esp_err_t e = qma_read(probe[i], &r, 1);
221→        ESP_LOGI(TAG, "REG 0x%02x %s = %s 0x%02x", probe[i], nm[i],
222→                 e == ESP_OK ? "ACK " : "NACK", r);
223→    }
224→
225→    uint8_t ranges[] = {0x01, 0x02, 0x04, 0x08, 0x0F};
226→    const char *rn[] = {"2g", "4g", "8g", "16g", "32g"};
227→    for (int i = 0; i < 5; i++) {
228→        uint8_t rb = 0xFF;
229→        qma_write_reg(0x0F, ranges[i]);
230→        vTaskDelay(pdMS_TO_TICKS(30));
231→        qma_read(0x0F, &rb, 1);
232→        ESP_LOGI(TAG, "RANGE wr=0x%02x(+-%s) rd=0x%02x %s",
233→                 ranges[i], rn[i], rb, (rb == ranges[i]) ? "接受" : "拒绝/不生效");
234→    }
235→    qma_write_reg(0x0F, 0x01);
236→    vTaskDelay(pdMS_TO_TICKS(30));
237→    qma_read(0x0F, &v, 1);
238→    ESP_LOGI(TAG, "RANGE 恢复 = 0x%02x (期望 0x01)", v);
239→    ESP_LOGI(TAG, "======== 鉴定结束 ========");
240→}
241→
242→static esp_err_t http_post_json(const char *json)
243→{
244→    esp_http_client_config_t cfg = {
245→        .url = SERVER_URL,
246→        .method = HTTP_METHOD_POST,
247→        .timeout_ms = 5000,
248→    };
249→    esp_http_client_handle_t client = esp_http_client_init(&cfg);
250→    if (client == NULL) {
251→        return ESP_FAIL;
252→    }
253→    esp_http_client_set_header(client, "Content-Type", "application/json");
254→    esp_http_client_set_post_field(client, json, strlen(json));
255→
256→    esp_err_t err = esp_http_client_perform(client);
257→    if (err == ESP_OK) {
258→        int status = esp_http_client_get_status_code(client);
259→        ESP_LOGI(TAG, "上报完成 HTTP %d", status);
260→        if (status != 200) {
261→            err = ESP_FAIL;
262→        }
263→    } else {
264→        ESP_LOGW(TAG, "上报失败: %s", esp_err_to_name(err));
265→    }
266→    esp_http_client_cleanup(client);
267→    return err;
268→}
269→
270→/* QMA6100P 14位数据组装：
271→ * MSB 寄存器 = DX[13:6]，LSB 寄存器 bit5:0 = DX[5:0]，bit7 = NEWDATA 标志
272→ * 14位二进制补码，bit13 为符号位 */
273→static inline int16_t qma_assemble14(uint8_t lsb, uint8_t msb)
274→{
275→    int16_t v = (int16_t)(((uint16_t)msb << 6) | (lsb & 0x3F));
276→    if (v & 0x2000) {
277→        v -= 0x4000;
278→    }
279→    return v;
280→}
281→
282→void app_main(void)
283→{
284→    ESP_ERROR_CHECK(nvs_flash_init());
285→    i2c_master_init();
286→    i2c_scan();
287→
288→    if (!qma6100p_init()) {
289→        ESP_LOGE(TAG, "IMU 初始化失败，停机（不发送假数据）");
290→        return;
291→    }
292→    imu_identify();
293→
294→    wifi_init_sta();
295→    /* 等 WiFi 拿到 IP */
296→    xEventGroupWaitBits(s_wifi_event_group, WIFI_CONNECTED_BIT,
297→                        pdFALSE, pdTRUE, portMAX_DELAY);
298→
299→    /* 摄像头视频流是独立功能：就算它挂了，也不许影响 IMU 上报链路 */
300→    if (camera_stream_start() != ESP_OK) {
301→        ESP_LOGW(TAG, "摄像头未就绪，IMU 上报链路继续工作");
302→    }
303→
304→    uint32_t seq = 0;
305→    while (1) {
306→        uint8_t raw[6];
307→        if (qma_read(0x01, raw, sizeof(raw)) != ESP_OK) {
308→            ESP_LOGE(TAG, "读取加速度计数据寄存器(0x01)失败");
309→            vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
310→            continue;
311→        }
312→
313→        /* QMA6100P：0x01 起 6 字节 = [DXL,DXM,DYL,DYM,DZL,DZM]，LSB 高位含 NEWDATA 标志 */
314→        int16_t ax_raw = qma_assemble14(raw[0], raw[1]);
315→        int16_t ay_raw = qma_assemble14(raw[2], raw[3]);
316→        int16_t az_raw = qma_assemble14(raw[4], raw[5]);
317→
318→        float ax = (ax_raw + CAL_X_OFF) / QMA_SENS_LSB_PER_G;
319→        float ay = (ay_raw + CAL_Y_OFF) / QMA_SENS_LSB_PER_G;
320→        float az = (az_raw - CAL_Z_OFF) / (QMA_SENS_LSB_PER_G * CAL_Z_SCALE);
321→
322→        char payload[256];
323→        int n = snprintf(payload, sizeof(payload),
324→                         "{\"device_id\":\"%s\",\"seq\":%lu,\"ts\":%lld,"
325→                         "\"ax\":%.4f,\"ay\":%.4f,\"az\":%.4f,"
326→                         "\"gx\":0.00,\"gy\":0.00,\"gz\":0.00}",
327→                         DEVICE_ID, (unsigned long)seq,
328→                         (long long)(esp_timer_get_time() / 1000),
329→                         ax, ay, az);
330→        if (n > 0 && n < (int)sizeof(payload)) {
331→            float norm = sqrtf(ax * ax + ay * ay + az * az);
332→            ESP_LOGI(TAG, "raw=[%d %d %d] ax=%.3f ay=%.3f az=%.3f |a|=%.3f",
333→                     ax_raw, ay_raw, az_raw, ax, ay, az, norm);
334→            http_post_json(payload);
335→        }
336→
337→        seq++;
338→        vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
339→    }
340→}
