157→<script>
158→const $ = (id) => document.getElementById(id);
159→const fmt = (v, n = 3) => (v === null || v === undefined) ? '—' : Number(v).toFixed(n);
160→
161→const SERIES = {
162→  acc: [['ax', '加速度 X', '#378ADD'], ['ay', '加速度 Y', '#1D9E75'], ['az', '加速度 Z', '#BA7517']],
163→  gyr: [['gx', '角速度 X', '#378ADD'], ['gy', '角速度 Y', '#1D9E75'], ['gz', '角速度 Z', '#BA7517']],
164→};
165→let MODE = 'acc';
166→let LAST = [];
167→
168→/* 服务端 API 地址：页面可能被静态预览器（非 8000 端口）或 file:// 打开，
169→ * 相对路径会指错地方，所以这里做自适应：
170→ *   - 从服务器打开（http/https）→ 跟随当前地址。这样本机、局域网、以后内网穿透
171→ *     或放到云上，页面都能自动指向"自己所在的那台服务器"，不用改代码；
172→ *   - 直接双击 html（file://）→ 退回本机 8000 端口的数据服务。 */
173→const API_BASE = (location.protocol === 'http:' || location.protocol === 'https:')
174→  ? location.origin
175→  : 'http://127.0.0.1:8000';
176→
177→/* ---------- 摄像头取流方式 ----------
178→ * 'server'（默认）：走 127.0.0.1:8000 的服务器中转。
179→ *   好处有三：① 网页不需要知道板子 IP，DHCP 换了地址也不受影响；
180→ *            ② 板子只跟服务器维持 1 路视频连接，开多少个网页都压不垮它；
181→ *            ③ 以后做远程访问，只要把服务器端口映射出去，数据和画面一次到位。
182→ * 'direct'：网页直接连板子 81 端口，仅用于排查「是服务器问题还是板子问题」。
183→ *   注意板子最多只扛得住 2 路并发，超过会互相拖垮。 */
184→const CAM_MODE = 'server';
185→const CAM_BASE = 'http://10.1.41.160:81';   // 仅 'direct' 模式使用
186→const CAM_STREAM   = CAM_MODE === 'server' ? API_BASE + '/api/camera' : CAM_BASE + '/stream';
187→const CAM_HEARTBEAT = CAM_MODE === 'server' ? API_BASE + '/api/camera/status' : CAM_BASE + '/ping';
188→/* ---------- 摄像头：自带掉线自愈 ----------
189→ * 之前只有一行 error 监听，一旦连接中断就永远停在「未连接」，只能手动刷新页面。
190→ * 现在做三件事：
191→ *   1) 每次重连都换一个 URL 时间戳，避免浏览器把上一次的失败结果缓存住；
192→ *   2) 失败后按 2 秒递增退避重试，不再一次性判死；
193→ *   3) 每 3 秒查一次状态（server 模式查 /api/camera/status，direct 模式查板子 /ping）。
194→ *      状态端点是毫秒级返回的轻量请求：连它都超时 = 服务被堵死，主动掐掉旧连接重建；
195→ *      它还活着但报告「没有人在看」= 我们的视频流其实已经断了，页面却不知道
196→ *      （画面停在最后一帧），同样重建。 */
197→(function mountCamera() {
198→  const img = document.getElementById('camStream');
199→  const st  = document.getElementById('camStatus');
200→  const btn = document.getElementById('btnCamRe');
201→  if (!img) return;
202→
203→  let retries = 0;            // 连续失败次数
204→  let retryTimer = null;      // 重试定时器
205→  let everOK = false;         // 是否曾经连上过
206→  let deadVotes = 0;          // /ping 连续失败次数
207→  let zeroVotes = 0;          // /ping 活着但自称 0 客户端的次数
208→
209→  function text(s) { st.textContent = s; }
210→
211→  function connect() {
212→    clearTimeout(retryTimer);
213→    if (retries === 0) text('连接中…');
214→    else text('第 ' + retries + ' 次重连…');
215→
216→    img.onload  = function () {
217→      retries = 0; zeroVotes = 0; everOK = true;
218→      text('实时画面 · 已连接');
219→    };
220→    img.onerror = function () {
221→      retries++;
222→      if (retries > 20) {
223→        text('未连接 · 请给板子重新上电后刷新本页面');
224→        return;
225→      }
226→      const wait = Math.min(2 * retries, 10);   // 2s、4s…封顶 10s 退避
227→      text('未连接 · ' + wait + ' 秒后重试（第 ' + retries + ' 次）');
228→      retryTimer = setTimeout(connect, wait * 1000);
229→    };
230→    /* 时间戳是必须的：不带它会命中浏览器缓存的重定向/错误状态 */
231→    img.src = CAM_STREAM + '?nocache=' + Date.now();
232→  }
233→
234→  function hardReconnect(reason) {
235→    text('检测到' + reason + '，正在重建连接…');
236→    retries = 0; zeroVotes = 0; deadVotes = 0;
237→    img.onload = img.onerror = null;
238→    img.src = '';                       // 先掐断，释放服务端的通路
239→    setTimeout(connect, 300);
240→  }
241→
242→  /* 解析状态端点，回答一个问题：画面还在流动吗？ */
243→  function parseLive(r, body) {
244→    if (CAM_MODE === 'server') {
245→      try {
246→        const j = JSON.parse(body);
247→        const age = j.last_frame_age;
248→        const flowing = j.state === 'streaming' && age !== null && age < 3;
249→        const note = age === null ? '尚无画面'
250→                                  : ' ' + age.toFixed(1) + ' 秒前的帧';
251→        return { alive: flowing, flowing: flowing, note: note, detail: j };
252→      } catch (e) {
253→        return { alive: false, flowing: false, note: '状态解析失败' };
254→      }
255→    }
256→    const m = body.match(/clients=(\d+)\/(\d+)/);
257→    const clients = m ? Number(m[1]) : null;
258→    return {
259→      alive: r.ok && clients !== null && clients > 0,
260→      flowing: clients > 0,
261→      note: clients === null ? '' : (clients + ' 路直连'),
262→    };
263→  }
264→
265→  /* 心跳：判断取流服务是不是还活着、画面是不是还在动 */
266→  async function heartbeat() {
267→    if (document.hidden) return;        // 页面在后台就别添乱
268→    const ctl = new AbortController();
269→    const to = setTimeout(() => ctl.abort(), 4000);
270→    try {
271→      const r = await fetch(CAM_HEARTBEAT + '?nocache=' + Date.now(),
272→                            { cache: 'no-store', signal: ctl.signal });
273→      const body = await r.text();
274→      clearTimeout(to);
275→      deadVotes = 0;
276→      const s = parseLive(r, body);
277→
278→      if (!s.alive) {
279→        /* 服务在，但没有画面流动 —— 我们的那条流其实已经断了 */
280→        if (++zeroVotes >= 2) hardReconnect('画面已停止');
281→        else text('实时画面 · 已连接（' + s.note.trim() + '）');
282→      } else {
283→        zeroVotes = 0;
284→        if (!everOK) text('服务在线，正在取画面…');
285→        else text('实时画面 · 已连接（' + s.note.trim() + '）');
286→      }
287→    } catch (e) {
288→      clearTimeout(to);
289→      if (++deadVotes >= 2) {
290→        deadVotes = 0;
291→        hardReconnect(CAM_MODE === 'server' ? '服务器无响应' : '板子无响应');
292→      } else if (retries === 0) {
293→        text('连接中…');
294→      }
295→    }
296→  }
297→
298→  btn.addEventListener('click', function () {
299→    retries = 0; deadVotes = 0; zeroVotes = 0; everOK = false;
300→    hardReconnect('手动重连');
301→  });
302→
303→  connect();
304→  setInterval(heartbeat, 3000);
305→})();
306→
307→function renderLegend() {
308→  $('legend').innerHTML = SERIES[MODE]
309→    .map(([, name, c]) => `<span><i style="background:${c}"></i>${name}</span>`).join('');
310→}
311→
312→function drawChart() {
313→  const cv = $('chart');
314→  const dpr = window.devicePixelRatio || 1;
315→  const w = cv.clientWidth || 900;
316→  const h = 240;
317→  cv.width = Math.round(w * dpr);
318→  cv.height = Math.round(h * dpr);
319→  const g = cv.getContext('2d');
320→  g.setTransform(dpr, 0, 0, dpr, 0, 0);
321→  g.clearRect(0, 0, w, h);
322→
323→  const pts = LAST.slice().reverse();      // 服务端返回倒序，这里还原成时间正序
324→  const keys = SERIES[MODE];
325→
326→  if (!pts.length) {
327→    g.fillStyle = '#6b6a65';
328→    g.font = '13px sans-serif';
329→    g.textAlign = 'center';
330→    g.fillText('暂无数据', w / 2, h / 2);
331→    return;
332→  }
333→
334→  const pl = 48, pr = 12, pt = 10, pb = 24;
335→  let min = Infinity, max = -Infinity;
336→  pts.forEach(p => keys.forEach(([k]) => {
337→    const v = Number(p[k]);
338→    if (v < min) min = v;
339→    if (v > max) max = v;
340→  }));
341→  if (!isFinite(min) || !isFinite(max)) { min = -1; max = 1; }
342→  if (max - min < 1e-6) { min -= 0.5; max += 0.5; }
343→  const pad = (max - min) * 0.12;
344→  min -= pad; max += pad;
345→
346→  const X = i => pl + (w - pl - pr) * (pts.length === 1 ? 0.5 : i / (pts.length - 1));
347→  const Y = v => pt + (h - pt - pb) * (1 - (v - min) / (max - min));
348→
349→  g.font = '11px sans-serif';
350→  g.strokeStyle = '#ebeae5';
351→  g.lineWidth = 1;
352→  g.textAlign = 'right';
353→  for (let i = 0; i <= 4; i++) {
354→    const v = min + (max - min) * i / 4;
355→    const yy = Math.round(Y(v)) + 0.5;
356→    g.beginPath(); g.moveTo(pl, yy); g.lineTo(w - pr, yy); g.stroke();
357→    g.fillStyle = '#6b6a65';
358→    g.fillText(v.toFixed(2), pl - 8, yy + 4);
359→  }
360→
361→  g.fillStyle = '#6b6a65';
362→  g.textAlign = 'left';
363→  g.fillText((pts[0].server_time || '').slice(11), pl, h - 6);
364→  g.textAlign = 'right';
365→  g.fillText((pts[pts.length - 1].server_time || '').slice(11), w - pr, h - 6);
366→
367→  keys.forEach(([k, , color]) => {
368→    g.strokeStyle = color;
369→    g.lineWidth = 1.8;
370→    g.lineJoin = 'round';
371→    g.beginPath();
372→    pts.forEach((p, i) => {
373→      const xx = X(i), yy = Y(Number(p[k]));
374→      if (i === 0) g.moveTo(xx, yy); else g.lineTo(xx, yy);
375→    });
376→    g.stroke();
377→  });
378→}
379→
380→$('btnAcc').onclick = () => { MODE = 'acc'; $('btnAcc').classList.add('on'); $('btnGyr').classList.remove('on'); renderLegend(); drawChart(); };
381→$('btnGyr').onclick = () => { MODE = 'gyr'; $('btnGyr').classList.add('on'); $('btnAcc').classList.remove('on'); renderLegend(); drawChart(); };
382→window.addEventListener('resize', drawChart);
383→
384→function setPill(cls, text) {
385→  const p = $('pill');
386→  p.className = 'pill ' + cls;
387→  p.textContent = text;
388→}
389→
390→async function tick() {
391→  try {
392→    const [lr, hr] = await Promise.all([
393→      fetch(API_BASE + '/api/latest').then(r => r.json()),
394→      fetch(API_BASE + '/api/history?limit=60').then(r => r.json())
395→    ]);
396→
397→    $('mthr').textContent = (lr.stale_seconds ?? '—') + ' 秒';
398→
399→    if (!lr.has_data) {
400→      setPill('idle', '暂无数据');
401→      $('dev').textContent = 'device: —';
402→      ['ax','ay','az','gx','gy','gz'].forEach(k => $(k).innerHTML = '—');
403→      $('mtime').textContent = $('mage').textContent = $('mseq').textContent = $('mip').textContent = '—';
404→      $('tbody').innerHTML = '<tr><td colspan="8" style="text-align:center;color:#6b6a65">暂无数据</td></tr>';
405→      LAST = [];
406→      drawChart();
407→      return;
408→    }
409→
410→    const r = lr.record;
411→    $('dev').textContent = 'device: ' + r.device_id;
412→    $('ax').innerHTML = fmt(r.ax) + '<span class="u">g</span>';
413→    $('ay').innerHTML = fmt(r.ay) + '<span class="u">g</span>';
414→    $('az').innerHTML = fmt(r.az) + '<span class="u">g</span>';
415→    $('gx').innerHTML = fmt(r.gx, 1) + '<span class="u">°/s</span>';
416→    $('gy').innerHTML = fmt(r.gy, 1) + '<span class="u">°/s</span>';
417→    $('gz').innerHTML = fmt(r.gz, 1) + '<span class="u">°/s</span>';
418→
419→    $('mtime').textContent = r.server_time;
420→    $('mage').textContent = r.age_seconds.toFixed(1) + ' 秒';
421→    $('mseq').textContent = r.seq;
422→    $('mip').textContent = r.src_ip || '—';
423→
424→    if (r.stale) {
425→      setPill('bad', '未更新 · 已 ' + r.age_seconds.toFixed(0) + ' 秒');
426→    } else {
427→      setPill('ok', '实时更新中');
428→    }
429→
430→    LAST = hr.records || [];
431→    drawChart();
432→
433→    const rows = LAST.slice(0, 8).map(x => `<tr>
434→      <td>${x.server_time}</td>
435→      <td>${fmt(x.ax)}</td><td>${fmt(x.ay)}</td><td>${fmt(x.az)}</td>
436→      <td>${fmt(x.gx,1)}</td><td>${fmt(x.gy,1)}</td><td>${fmt(x.gz,1)}</td>
437→      <td>${x.seq}</td></tr>`).join('');
438→    $('tbody').innerHTML = rows || '<tr><td colspan="8" style="text-align:center;color:#6b6a65">暂无数据</td></tr>';
439→  } catch (e) {
440→    setPill('warn', '无法连接服务');
441→  }
442→}
443→
444→renderLegend();
445→tick();
446→setInterval(tick, 1000);
447→</script>
448→</body>
449→</html>
