{"command": "$out = @()
$out += "===== 监听 8000 端口的进程 ====="
$conns = Get-NetTCPConnection -LocalPort 8000 -ErrorAction SilentlyContinue
if ($conns) { $conns | ForEach-Object { "  State=$($_.State)  Local=$($_.LocalAddress):$($_.LocalPort)  PID=$($_.OwningProcess)" } | ForEach-Object { $out += $_ } } else { $out += "  (无进程监听 8000)" }
$out += ""
$out += "===== python 进程 ====="
$py = Get-Process python -ErrorAction SilentlyContinue
if ($py) { $py | ForEach-Object { "  PID=$($_.Id)  Start=$($_.StartTime)  Mem=$([math]::Round($_.WorkingSet64/1MB,1))MB" } | ForEach-Object { $out += $_ } } else { $out += "  (没有 python 进程在跑)" }
$out += ""
$out += "===== 本机 IP ====="
Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue | Where-Object { $_.IPAddress -notmatch '^127\.' } | ForEach-Object { "  $($_.IPAddress)  ($($_.InterfaceAlias))" } | ForEach-Object { $out += $_ }
$out += ""
$out += "===== 尝试访问本机 8000 /api/latest ====="
try { $r = Invoke-WebRequest -Uri "http://127.0.0.1:8000/api/latest" -TimeoutSec 4 -UseBasicParsing; $out += "  HTTP $($r.StatusCode): $($r.Content)" } catch { $out += "  访问失败: $($_.Exception.Message)" }
$out | Out-File "D:\aijiaohu\week1\debug_logs\_diag_srv.txt" -Encoding utf8", "description": "诊断 8000 端口监听、python 进程、本机 IP 与接口连通性"}

