output.text:
  1→/* AI 交互课 第1周 —— ESP32-S3-EYE 板端固件（板载三轴加速度计）
  2→ *
  3→ * 功能：连 WiFi -> I2C 读板载加速度计（GPIO4=SDA, GPIO5=SCL, 地址 0x12）
  4→ *       -> 每 1 秒 HTTP POST 一条 JSON 到服务端
  5→ *
  6→ * ====== 关于芯片型号（重要，调试踩坑的根源）======
  7→ * 原理图和官方手册标注的是 QMA7981，但**本板实装为 QMA6100P**。
  8→ * 两者是 pin-to-pin 兼容的换代关系（QMA7981 已 EOL 停产），封装、
  9→ * I2C 地址(0x12)、14 位 ADC 都一样，所以硬件上换料看不出来。
 10→ * 本板的实测证据（上电时 imu_identify() 会自动打印一遍）：
 11→ *   1) CHIP_ID(0x00) = 0x90  -> QMA6100P（QMA7981 公开手册为 0xE7）
 12→ *   2) QMA6100P 手册特有寄存器 0x33/0x45/0x46/0x4A/0x56/0x5F 均有有效应答
 13→ *   3) 量程位编码 0x01/0x02/0x04/0x08/0x0F(±2/4/8/16/32g) 全部被接受，
 14→ *      而 0x00 是非法值 —— 当初按 QMA7981 手册写 0x00 导致模长异常 1.5g
 15→ * 结论：本驱动按 QMA6100P 的真实寄存器行为编写，不要照 QMA7981 手册改。
 16→ *
 17→ * 注意：QMA6100P 只有三轴加速度，没有陀螺仪 —— gx/gy/gz 固定发 0。
 18→ *
 19→ * 使用前改 3 个宏：WIFI_SSID / WIFI_PASS / SERVER_URL
 20→ * 编译烧录（用桌面的 ESP-IDF 5.4 CMD）：
 21→ *     idf.py set-target esp32s3
 22→ *     idf.py build
 23→ *     idf.py -p COM5 flash monitor
 24→ *
 25→ * SERVER_URL 填电脑的局域网 IP（如 http://192.168.1.23:8000/api/data），
 26→ * 不能用 127.0.0.1 —— 那是板子自己。
 27→ */
 28→
 29→#include <stdio.h>
 30→#include <string.h>
 31→#include <math.h>
 32→#include "freertos/FreeRTOS.h"
 33→#include "freertos/task.h"
 34→#include "freertos/event_groups.h"
 35→#include "esp_log.h"
 36→#include "esp_wifi.h"
 37→#include "esp_event.h"
 38→#include "esp_netif.h"
 39→#include "esp_http_client.h"
 40→#include "esp_timer.h"
 41→#include "nvs_flash.h"
 42→#include "driver/i2c.h"
 43→#include "camera_stream.h"
 44→
 45→/* ============ 需要按实际情况修改 ============ */
 46→#define WIFI_SSID      "431"
 47→#define WIFI_PASS      "88888888"
 48→#define SERVER_URL     "http://10.1.41.18:8000/api/data"
 49→#define DEVICE_ID      "team01-esp32s3eye"
 50→
 51→/* ============ ESP32-S3-EYE 固定接线（不用改） ============ */
 52→#define I2C_SDA_GPIO   4      /* 与摄像头 SCCB 共用总线 */
 53→#define I2C_SCL_GPIO   5
 54→#define I2C_PORT       I2C_NUM_0
 55→#define I2C_FREQ_HZ    400000
 56→#define QMA6100P_ADDR   0x12
 57→
 58→/* 灵敏度：±2g 量程、14位输出 下每 1g 对应的原始计数值。
 59→ * QMA6100P 数据为 14 位左对齐（先组装 16 位再算术右移 2 位），
 60→ * ±2g 满量程 16384 计数跨 4g => 4096 LSB/g。 */
 61→#define QMA_SENS_LSB_PER_G  4096.0f
 62→
 63→#define POST_INTERVAL_MS  1000
 64→
 65→/* ===== 实测标定（旋转实验：面朝上/朝下静止两点法拟合） =====
 66→ * 本板 QMA6100P（chip_id 0x90）零偏偏大：未标定静止模长 0.78~1.6g 漂移。
 67→ * X 零偏 -0.553g、Y 零偏 -0.148g、Z 零偏 +0.389g、Z 灵敏度系数 0.912，
 68→ * 标定后各静置姿态模长 0.97~1.01。换板子需重新标定。 */
 69→#define CAL_X_OFF    2265.0f   /* 计数 = 0.553g * 4096 */
 70→#define CAL_Y_OFF     608.0f   /* 计数 = 0.148g * 4096 */
 71→#define CAL_Z_OFF    1594.0f   /* 计数 = 0.389g * 4096 */
 72→#define CAL_Z_SCALE    0.912f
 73→/* =========================================== */
 74→/* =========================================== */
 75→
 76→static const char *TAG = "week1";
 77→static EventGroupHandle_t s_wifi_event_group;
 78→#define WIFI_CONNECTED_BIT BIT0
 79→
 80→static void wifi_event_handler(void *arg, esp_event_base_t base,
 81→                               int32_t id, void *data)
 82→{
 83→    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
 84→        esp_wifi_connect();
 85→    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
 86→        ESP_LOGW(TAG, "WiFi 断开，重试中...");
 87→        esp_wifi_connect();
 88→    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
 89→        ip_event_got_ip_t *ev = (ip_event_got_ip_t *)data;
 90→        ESP_LOGI(TAG, "拿到 IP: " IPSTR, IP2STR(&ev->ip_info.ip));
 91→        xEventGroupSetBits(s_wifi_event_group, WIFI_CONNECTED_BIT);
 92→    }
 93→}
 94→
 95→static void wifi_init_sta(void)
 96→{
 97→    s_wifi_event_group = xEventGroupCreate();
 98→    ESP_ERROR_CHECK(esp_netif_init());
 99→    ESP_ERROR_CHECK(esp_event_loop_create_default());
100→    esp_netif_create_default_wifi_sta();
101→
102→    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
103→    ESP_ERROR_CHECK(esp_wifi_init(&cfg));
104→
105→    ESP_ERROR_CHECK(esp_event_handler_register(WIFI_EVENT, ESP_EVENT_ANY_ID,
106→                                               &wifi_event_handler, NULL));
107→    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_STA_GOT_IP,
108→                                               &wifi_event_handler, NULL));
109→
110→    wifi_config_t wifi_cfg = {0};
111→    strncpy((char *)wifi_cfg.sta.ssid, WIFI_SSID, sizeof(wifi_cfg.sta.ssid) - 1);
112→    strncpy((char *)wifi_cfg.sta.password, WIFI_PASS, sizeof(wifi_cfg.sta.password) - 1);
113→    wifi_cfg.sta.threshold.authmode = WIFI_AUTH_WPA2_PSK;
114→
115→    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
116→    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_cfg));
117→    ESP_ERROR_CHECK(esp_wifi_start());
118→    ESP_LOGI(TAG, "WiFi 启动，等待连接 %s ...", WIFI_SSID);
119→}
