284→/* ================= 设备自身状态：芯片温度 + 堆内存 =================
285→ *
286→ * 温度：ESP32-S3 芯片内部自带一颗温度传感器，不用外接任何元件。
287→ *   注意它测的是**芯片裸片温度**，不是环境温度——芯片自己会发热，
288→ *   通常比室温高几度。适合观察"板子负载/温升趋势"，不能当室温计用。
289→ *
290→ * 内存：esp_get_free_heap_size() 返回当前可用堆（字节），
291→ *   esp_get_minimum_free_heap_size() 返回开机以来的历史最低值，
292→ *   后者是判断"有没有内存泄漏"的关键：它随时间持续下降 = 有泄漏。
293→ *
294→ * 这两个量与 IMU 一起上报，网页上就能同时看到"被测对象的物理量"
295→ * 和"设备自身的健康度"。初始化失败不影响主链路，只是字段报 null。
296→ * ================================================================ */
297→static temperature_sensor_handle_t s_tsens = NULL;
298→
299→static void temp_sensor_init(void)
300→{
301→    /* 量程必须完整落在芯片预定义档位内，否则 install 会报
302→     * "Out of testing range" + ESP_ERR_INVALID_ARG（实测踩过）。
303→     * ESP32-S3 只有 5 档：50~125 / 20~100 / -10~80 / -30~50 / -40~20，
304→     * 其中 -10~80 误差最小(±1°C)，且完全覆盖芯片工作温区(通常 40~60°C)。 */
305→    temperature_sensor_config_t cfg = TEMPERATURE_SENSOR_CONFIG_DEFAULT(-10, 80);
306→    esp_err_t err = temperature_sensor_install(&cfg, &s_tsens);
307→    if (err != ESP_OK) {
308→        ESP_LOGW(TAG, "温度传感器 install 失败: %s (%d), temp_c 将上报 null",
309→                 esp_err_to_name(err), err);
310→        s_tsens = NULL;
311→        return;
312→    }
313→    err = temperature_sensor_enable(s_tsens);
314→    if (err != ESP_OK) {
315→        ESP_LOGW(TAG, "温度传感器 enable 失败: %s (%d), temp_c 将上报 null",
316→                 esp_err_to_name(err), err);
317→        s_tsens = NULL;
318→        return;
319→    }
320→    float t = 0;
321→    err = temperature_sensor_get_celsius(s_tsens, &t);
322→    ESP_LOGI(TAG, "温度传感器就绪，当前 %.1f C (读取返回 %s)", t, esp_err_to_name(err));
323→}
324→
325→void app_main(void)
326→{
327→    ESP_ERROR_CHECK(nvs_flash_init());
328→    temp_sensor_init();
329→    i2c_master_init();
330→    i2c_scan();
331→
332→    if (!qma6100p_init()) {
333→        ESP_LOGE(TAG, "IMU 初始化失败，停机（不发送假数据）");
334→        return;
335→    }
336→    imu_identify();
337→
338→    wifi_init_sta();
339→    /* 等 WiFi 拿到 IP */
340→    xEventGroupWaitBits(s_wifi_event_group, WIFI_CONNECTED_BIT,
341→                        pdFALSE, pdTRUE, portMAX_DELAY);
342→
343→    /* 摄像头视频流是独立功能：就算它挂了，也不许影响 IMU 上报链路 */
344→    if (camera_stream_start() != ESP_OK) {
345→        ESP_LOGW(TAG, "摄像头未就绪，IMU 上报链路继续工作");
346→    }
347→
348→    uint32_t seq = 0;
349→    while (1) {
350→        uint8_t raw[6];
351→        if (qma_read(0x01, raw, sizeof(raw)) != ESP_OK) {
352→            ESP_LOGE(TAG, "读取加速度计数据寄存器(0x01)失败");
353→            vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
354→            continue;
355→        }
356→
357→        /* QMA6100P：0x01 起 6 字节 = [DXL,DXM,DYL,DYM,DZL,DZM]，LSB 高位含 NEWDATA 标志 */
358→        int16_t ax_raw = qma_assemble14(raw[0], raw[1]);
359→        int16_t ay_raw = qma_assemble14(raw[2], raw[3]);
360→        int16_t az_raw = qma_assemble14(raw[4], raw[5]);
361→
362→        float ax = (ax_raw + CAL_X_OFF) / QMA_SENS_LSB_PER_G;
363→        float ay = (ay_raw + CAL_Y_OFF) / QMA_SENS_LSB_PER_G;
364→        float az = (az_raw - CAL_Z_OFF) / (QMA_SENS_LSB_PER_G * CAL_Z_SCALE);
365→
366→        /* —— 读设备自身状态：芯片温度 + 堆内存 ——
367→         * 温度读不到时上报 JSON 的 null（而不是 0），免得网页显示 "0 °C"
368→         * 这种看起来像真的、其实是假的读数。 */
369→        float temp_c = 0.0f;
370→        char tbuf[16];
371→        bool temp_ok = (s_tsens != NULL) &&
372→                       (temperature_sensor_get_celsius(s_tsens, &temp_c) == ESP_OK);
373→        snprintf(tbuf, sizeof(tbuf), temp_ok ? "%.1f" : "null", temp_c);
374→
375→        uint32_t free_heap = esp_get_free_heap_size();
376→        uint32_t min_free  = esp_get_minimum_free_heap_size();
377→
378→        char payload[320];
379→        int n = snprintf(payload, sizeof(payload),
380→                         "{\"device_id\":\"%s\",\"seq\":%lu,\"ts\":%lld,"
381→                         "\"ax\":%.4f,\"ay\":%.4f,\"az\":%.4f,"
382→                         "\"gx\":0.00,\"gy\":0.00,\"gz\":0.00,"
383→                         "\"temp_c\":%s,\"free_heap\":%lu,\"min_free_heap\":%lu}",
384→                         DEVICE_ID, (unsigned long)seq,
385→                         (long long)(esp_timer_get_time() / 1000),
386→                         ax, ay, az,
387→                         tbuf,
388→                         (unsigned long)free_heap, (unsigned long)min_free);
389→        if (n > 0 && n < (int)sizeof(payload)) {
390→            float norm = sqrtf(ax * ax + ay * ay + az * az);
391→            ESP_LOGI(TAG, "raw=[%d %d %d] ax=%.3f ay=%.3f az=%.3f |a|=%.3f"
392→                          " | %sC 堆%luKB(最低%luKB)",
393→                     ax_raw, ay_raw, az_raw, ax, ay, az, norm,
394→                     tbuf,
395→                     (unsigned long)(free_heap / 1024),
396→                     (unsigned long)(min_free / 1024));
397→            http_post_json(payload);
398→        }
399→
400→        seq++;
401→        vTaskDelay(pdMS_TO_TICKS(POST_INTERVAL_MS));
402→    }
403→}
404→

