 40→  .grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 16px; }
 41→  @media (max-width: 720px) { .grid { grid-template-columns: repeat(2, 1fr); } }
 42→  .card {
 43→    background: var(--card); border: 1px solid var(--border);
 44→    border-radius: 12px; padding: 14px 16px;
 45→  }
 46→  .card .k { color: var(--muted); font-size: 12px; letter-spacing: .04em; }
 47→  .card .v {
 48→    font-size: 26px; font-weight: 600; font-variant-numeric: tabular-nums;
 49→    font-family: ui-monospace, Consolas, monospace; margin-top: 2px;
 50→  }
 51→  .card .u { color: var(--muted); font-size: 12px; margin-left: 4px; font-weight: 400; }
 52→  .meta {
 53→    background: var(--card); border: 1px solid var(--border); border-radius: 12px;
 54→    padding: 12px 16px; display: flex; gap: 24px; flex-wrap: wrap; margin-bottom: 16px;
 55→  }
 56→  .meta div { font-size: 13px; color: var(--muted); }
 57→  .meta b { color: var(--text); font-weight: 500; font-variant-numeric: tabular-nums; }
 58→  h2 { font-size: 14px; font-weight: 600; margin: 20px 0 8px; }
 59→  table { width: 100%; border-collapse: collapse; background: var(--card);
 60→          border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
 61→  th, td { padding: 8px 12px; text-align: right; font-size: 13px;
 62→           font-variant-numeric: tabular-nums; border-bottom: 1px solid var(--border); }
 63→  th:first-child, td:first-child { text-align: left; }
 64→  th { background: #faf9f6; color: var(--muted); font-weight: 500; }
 65→  tr:last-child td { border-bottom: none; }
 66→  .hint { color: var(--muted); font-size: 12px; margin-top: 12px; }
 67→  .chartbox {
 68→    background: var(--card); border: 1px solid var(--border);
 69→    border-radius: 12px; padding: 12px 16px 10px; margin-bottom: 16px;
 70→  }
 71→  .charthead { display: flex; align-items: center; gap: 12px; margin-bottom: 8px; }
 72→  .charthead h2 { margin: 0; }
 73→  .seg { margin-left: auto; display: flex; align-items: center; gap: 8px; }
 74→  .seg button {
 75→    border: 1px solid var(--border); background: #faf9f6; color: var(--muted);
 76→    padding: 4px 12px; font-size: 13px; cursor: pointer; font-family: inherit;
 77→    border-radius: 8px;
 78→  }
 79→  .seg button:hover { background: #f1efe8; }
 80→  canvas { width: 100%; height: 240px; display: block; }
 81→  .legend { display: flex; gap: 18px; font-size: 12px; color: var(--muted); margin-top: 8px; flex-wrap: wrap; }
 82→  .legend i {
 83→    display: inline-block; width: 12px; height: 3px; border-radius: 2px;
 84→    margin-right: 6px; vertical-align: middle;
 85→  }
 86→</style>
 87→</head>
 88→<body>
 89→<div class="wrap">
 90→  <header>
 91→    <h1>IMU 传感数据实时展示</h1>
 92→    <span class="dev" id="dev">device: —</span>
 93→    <span class="pill idle" id="pill">等待数据</span>
 94→  </header>
 95→
 96→  <!-- 上半：被测对象的物理量（三轴加速度 + 合成模长）
 97→       下半：设备自身健康度（芯片温度、剩余堆内存）
 98→       板载 QMA6100P 是纯三轴加速度计（无陀螺仪），故不显示角速度。 -->
